#include <iostream>
#include <cctype>

int main()
{
    const char samples[] = {'8', '#', 'A', 'b', '&', 'F', 'J'};

    std::cout << "Testing alphanumeric functions:\n";
    for (char ch : samples)
    {
        unsigned char uc = static_cast<unsigned char>(ch);
        std::cout << "Char '" << ch << "': "
                  << (std::isdigit(uc) ? "digit " : "not-digit ")
                  << (std::isalpha(uc) ? "alpha " : "not-alpha ")
                  << (std::isalnum(uc) ? "alnum " : "not-alnum ")
                  << (std::isxdigit(uc) ? "xdigit" : "not-xdigit")
                  << '\n';
    }
    return 0;
}

#include <iostream>
#include <cctype>

int main()
{
    const char letters[] = {'p', 'P', '5', '!'};

    for (char ch : letters)
    {
        unsigned char uc = static_cast<unsigned char>(ch);
        std::cout << ch << ": islower=" << (std::islower(uc) ? 1 : 0)
                  << ", isupper=" << (std::isupper(uc) ? 1 : 0) << '\n';
    }

    std::cout << "'u' to upper: " << static_cast<char>(std::toupper(static_cast<unsigned char>('u'))) << '\n';
    std::cout << "'7' to upper: " << static_cast<char>(std::toupper(static_cast<unsigned char>('7'))) << '\n';
    std::cout << "'L' to lower: " << static_cast<char>(std::tolower(static_cast<unsigned char>('L'))) << '\n';

    return 0;
}

#include <iostream>
#include <cctype>

int main()
{
    const char testChars[] = {' ', ';', '\n', '$', 'Q'};

    std::cout << "Testing space, punct, print, and graph:\n";
    for (char c : testChars)
    {
        unsigned char uc = static_cast<unsigned char>(c);
        std::cout << "Char [" << (c == '\n' ? "\\n" : (c == ' ' ? "' '" : std::string(1, c))) << "] -> "
                  << "space:" << (std::isspace(uc) ? 1 : 0) << " "
                  << "cntrl:" << (std::iscntrl(uc) ? 1 : 0) << " "
                  << "punct:" << (std::ispunct(uc) ? 1 : 0) << " "
                  << "print:" << (std::isprint(uc) ? 1 : 0) << " "
                  << "graph:" << (std::isgraph(uc) ? 1 : 0) << '\n';
    }
    return 0;
}
